import sys;sys.path.insert(0,__import__('os').path.dirname(__file__));from mk import I
def P(i): return '매시간_5제_누적_최고난도-%03d'%i

I(P(41),"예상 오답 — $|\\sin2nx|$의 평균을 $\\frac2\\pi$로 바꿔 $\\max$ 안에 넣거나, 큰 값을 항상 진동 쪽으로 본 경우",
 ["한 주기 $\\frac\\pi{2n}$마다 적분 $=\\frac\\pi{2n}g(c)$, $c$는 그 구간의 $\\sin x$ — 단조성으로 끼움.",
  "$\\sin u\\ge\\sin x$인 경계각이 $x$ 자신 → $\\pi g(\\sin x)=2x\\sin^3x+\\int_x^{\\pi-x}\\sin^3u\\,du$."],
 {'C1':("$f_n$",r"$\sin x$와 $|\sin2nx|$ 중 작지 않은 값."),'C3':("$a_n$",r"$\int_0^{\pi/2}f_n^3dx$."),'C4':("극한",r"$\frac q{p\pi}$."),'C5':("묻는 것",r"$p+q$."),'C6':("서로소",r"기약분수.")},
 [("빠른 진동의 평균",[r"한 주기 평균으로 대체 — 끼움으로 정당화."]),("부분적분",[r"$\int x\sin^3x\,dx$."])],
 [("의도",['C1']),("주기",['C1']),("$g(c)$",['C3']),("성질",['C3']),("끼우기",['C4']),("경계각",['C1']),("식",['C3']),("부분적분",['C4']),("적분값",['C4']),("답",['C4','C5','C6'])],
 [("평균의 위치",'C1',[r"$\max$를 먼저 취한 뒤 평균 — 순서를 바꾸면 틀림."]),("경계각",'C1',[r"$[0,\pi]$에서 $\sin u\ge\sin x$ ⇔ $x\le u\le\pi-x$."])],
 [("변형 · 세제곱 대신 일차",[r"(같은 $f_n$에 대하여) $a_n=\int_0^{\frac\pi2}f_n(x)dx$라 할 때 $\lim_{n\to\infty}a_n=\frac q{p\pi}$이다. $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)"],5,r"$\pi g(\sin x)=2x\sin x+2\cos x$ → $\frac4\pi$.")],
 "빠른 진동 × 느린 변화 → 한 주기 평균 + 끼움.")

I(P(42),"예상 오답 — 주어진 대로 $z=t$ 단면(렌즈)을 적분하다 계산이 막히거나 아래쪽 경계를 남겨 넓이를 틀린 경우",
 ["입체: $(x-z)^2+y^2\\le4$, $(x+2z)^2+y^2\\le4$, $z\\ge0$ — 두 기울어진 원기둥.",
  "$y=k$로 자르면 일차부등식 → 삼각형, 넓이 $\\frac23(4-k^2)$."],
 {'C1':("$D_t$",r"평면 $z=t$에서 $\mathrm A(t,0,t)$, $\mathrm B(-2t,0,t)$까지 거리 $2$ 이하."),'C2':("부피",r"$\frac qp$."),'C3':("묻는 것",r"$p+q$."),'C4':("서로소",r"기약분수.")},
 [("단면 선택",[r"적분하기 쉬운 방향으로 자르기."]),("일차부등식 영역",[r"삼각형 꼭짓점."])],
 [("의도",['C1']),("입체",['C1']),("$y=k$ 단면",['C1']),("부등식",['C1']),("흡수",['C1']),("단면",['C1']),("삼각형",['C1']),("적분 준비",['C2']),("부피",['C2']),("답",['C3','C4'])],
 [("흡수",'C1',[r"$x-s\le0$, $\frac{-x-s}2\le0$ — $z\ge0$이 더 강함."]),("$s=\\sqrt{4-k^2}$",'C1',[r"$|y|\le2$."])],
 [("변형 · $\\mathrm B(-3t,0,t)$",[r"좌표공간에서 $0$ 이상의 실수 $t$에 대하여 평면 $z=t$ 위에 있고 두 점 $\mathrm A(t,\,0,\,t)$, $\mathrm B(-3t,\,0,\,t)$로부터의 거리가 모두 $2$ 이하인 점 전체의 집합을 $D_t$라 하자. $D_t$를 모두 모아 만든 입체의 부피가 $\frac qp$일 때, $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)"],19,r"삼각형 높이 $\frac s2$ → 넓이 $\frac{s^2}2$, 부피 $\frac{16}3$.")],
 "어려운 단면 → 다른 방향으로 자르면 일차.")

I(P(43),"예상 오답 — $X+Y=4$를 그대로 두고 경우를 세다 $X=Y$를 놓쳐 분모를 크게 잡은 경우",
 ["가리킴 총 $8$번을 받은 사람별로: $2X+(8-X-Y)=8$ → $X=Y$, 조건은 $X=2$.",
  "짝수 자리 사탕은 홀수 자리 선택으로만 정해짐 → 두 원형 묶음이 독립."],
 {'C1':("원탁",r"$8$명."),'C2':("선택",r"양옆 중 하나를 확률 $\frac12$로, 독립."),'C3':("사탕·노래",r"두 번 받음 → 사탕, 못 받음 → 노래."),
  'C4':("조건",r"사탕 수 + 노래 수 $=4$; 사탕 받는 둘이 이웃할 확률 $\frac qp$."),'C5':("묻는 것",r"$p+q$."),'C6':("서로소",r"기약분수.")},
 [("이중 계산",[r"보낸 수 = 받은 수."]),("홀짝 분리",[r"자리 $i$는 $i\pm1$의 선택으로 결정."])],
 [("의도",['C3']),("전체",['C2']),("$X=Y$",['C3','C4']),("홀짝",['C1','C2']),("RL 세기",['C3']),("$X=2$ 경우",['C4']),("이웃",['C4']),("답",['C5','C6'])],
 [("$X=Y$",'C4',[r"합 $4$는 사탕 $2$명 + 노래 $2$명."]),("이웃",'C4',[r"이웃은 홀짝이 다름 → 묶음마다 하나씩."])],
 [("변형 · $10$명",[r"원탁에 $10$명이 둘러앉아 (같은 규칙으로) 각자 양옆 중 한 명을 가리킨다. 사탕을 받는 사람의 수와 노래를 부르는 사람의 수의 합이 $4$일 때, 사탕을 받는 사람 중 서로 이웃하여 앉은 두 사람이 있을 확률이 $\frac qp$이다. $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)"],15,r"$\frac4{11}$.")],
 "보낸 수 = 받은 수 → $X=Y$, 홀짝 분리.")

I(P(44),"예상 오답 — 경로 길이를 특정 점 $\\mathrm P$에서 계산해 $a$를 구하려다 막히거나, 선분 $\\mathrm{PF}$가 쌍곡선의 다른 가지와 만난다고 본 경우",
 ["$\\overline{\\mathrm{AP}}+\\overline{\\mathrm{PQ}}+\\overline{\\mathrm{QF'}}=(16-x)+(x+4)-\\overline{\\mathrm{QF}}+\\overline{\\mathrm{QF}}+2a=20+2a$.",
  "$h(\\mathrm X)=\\overline{\\mathrm{XF'}}-\\overline{\\mathrm{XF}}$가 선분 위에서 $\\mathrm F$ 쪽으로 증가 → 만날 조건 $h(\\mathrm P)\\le2a$."],
 {'C1':("두 곡선",r"포물선 $C_1$(초점 원점, 준선 $x=-4$), 쌍곡선 $C_2$(초점 $\mathrm F$, $\mathrm F'(-6,0)$, 주축 $2a$)."),'C2':("점",r"$\mathrm Q$, $\mathrm A$의 정의."),
  'C3':("어떤 점",r"만나는 어떤 $\mathrm P$에서."),'C4':("경로",r"$=25$."),'C6':("호",r"만나는 $\mathrm P$ 전체 = 호 $\mathrm R_1\mathrm R_2$."),'C7':("묻는 것",r"$\overline{\mathrm R_1\mathrm R_2}^2$.")},
 [("포물선·쌍곡선 정의",[r"$\overline{\mathrm{PF}}=x+4$, $\overline{\mathrm{QF'}}-\overline{\mathrm{QF}}=2a$."]),("사잇값 정리",[r"연속함수 $h$."])],
 [("의도",['C1']),("경로",['C2']),("식",['C4']),("$a$",['C3','C4']),("$h$",['C6']),("가지",['C6']),("부등식",['C6']),("풀이",['C6']),("끝점",['C6']),("답",['C7'])],
 [("$\\mathrm P$에 무관",'C3',[r"'어떤 $\mathrm P$' 하나로 충분."]),("$x<16$",'C2',[r"$\overline{\mathrm{AP}}=16-x$ 부호 확인."])],
 [("변형 · 경로 $24$",[r"(같은 $C_1$, $C_2$, $\mathrm Q$, $\mathrm A$에 대하여) 선분 $\mathrm{PF}$가 $C_2$와 만나는 어떤 점 $\mathrm P$에 대하여 $\overline{\mathrm{AP}}+\overline{\mathrm{PQ}}+\overline{\mathrm{QF'}}=24$이다. 선분 $\mathrm{PF}$가 $C_2$와 만나도록 하는 $C_1$ 위의 점 $\mathrm P$ 전체가 두 점 $\mathrm R_1$, $\mathrm R_2$를 양 끝으로 하는 $C_1$의 일부분일 때, $\overline{\mathrm R_1\mathrm R_2}^2$의 값을 구하시오."],160,r"$a=2$, $x\le3$, $y^2=40$.")],
 "공유 초점 → 정의를 이어 붙인 일정한 경로.")

I(P(45),"예상 오답 — (나)로 $a=\\frac{79}{18}$을 버리지 않거나, $k=54$에서 끝점 근 $x=6$을 빠뜨린 경우",
 ["$N(p)$ = $p$를 포함하는 단조 구간 함숫값 범위의 개수.",
  "(가)에서 후보 $a=3$, $\\frac{79}{18}$; (나)가 극솟값 음수인 후보 제거."],
 {'C1':("함수",r"$f(0)=0$, $f'(1)=f'(a)=0$, $1<a<6$."),'C2':("$N(p)$",r"$[0,6]$에서 $f=p$의 근의 개수."),'C3':("(가)",r"$N=3$인 $p$는 길이 $4$인 구간."),
  'C4':("(나)",r"$N=2$인 $p$는 $2$개."),'C5':("묻는 것",r"$\sum_{k=-100}^{100}N(k)$.")},
 [("단조 구간",[r"구간마다 근은 많아야 하나."]),("경우 나누기",[r"$f(a)\gtrless0$, $f(1)\gtrless f(6)$."])],
 [("의도",['C2']),("$f$",['C1']),("구조",['C2']),("경계",['C3']),("후보",['C3']),("(나)",['C4']),("끝값",['C2']),("답",['C5'])],
 [("$N=2$ 무수히",'C4',[r"$f(a)<0$이면 $(f(a),0)$ 전체에서 $N=2$."]),("$k=54$",'C2',[r"닫힌구간이라 $x=6$ 포함."])],
 [("변형 · $\\sum kN(k)$",[r"(같은 조건에서) $\sum_{k=-100}^{100}k\,N(k)$의 값을 구하시오."],1501,r"$1\cdot3+2\cdot3+3\cdot3+4\cdot2+\sum_{5}^{54}k$.")],
 "근의 개수 = 함숫값 범위의 겹침 → 끝값 주의.")
